"""Adapter for provider payment notifications.

The wire protocol is described in ``docs/provider-notifications.md``. A
delivery is authenticated over the exact bytes received, must fall inside the
replay window, and is then normalized into the four fields consumed by the
account-crediting worker.
"""

import hashlib
import hmac
import json
import math
import re

from payhook.errors import InvalidNotification

TIMESTAMP_HEADER = "X-Pay-Timestamp"
SIGNATURE_HEADER = "X-Pay-Signature"

SIGNATURE_SCHEME = "v1"
MAX_CLOCK_SKEW_SECONDS = 300

_TIMESTAMP = re.compile(r"[+-]?[0-9]+")
_SIGNATURE = re.compile(r"v1=([0-9a-fA-F]+)")
_CURRENCY = re.compile(r"[A-Z]{3}")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    The result is a new dictionary holding ``event_id``, ``account_id``,
    ``amount_minor`` and ``currency``; every other request field is dropped.
    Raises :class:`payhook.errors.InvalidNotification` for a delivery that is
    unsigned, tampered with, stale, malformed, or missing a required field.
    """
    body = _as_bytes(raw_body, "request body")
    normalized = _normalized_headers(headers)
    timestamp_header = _required_header(normalized, TIMESTAMP_HEADER)
    signature_header = _required_header(normalized, SIGNATURE_HEADER)

    timestamp = _parse_timestamp(timestamp_header)
    _verify_signature(body, timestamp_header, signature_header, secret)
    _reject_stale(timestamp, now)

    payload = _decode_payload(body)
    return {
        "event_id": _required_text(payload, "event_id"),
        "account_id": _required_text(payload, "account_id"),
        "amount_minor": _required_amount(payload, "amount_minor"),
        "currency": _required_currency(payload, "currency"),
    }


def _as_bytes(value, label):
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value)
    if isinstance(value, str):
        return value.encode("utf-8")
    raise InvalidNotification("%s must be bytes" % label)


def _normalized_headers(headers):
    """Map lowercased header names to values; HTTP field names are caseless."""
    if headers is None:
        return {}
    entries = headers.items() if hasattr(headers, "items") else headers
    try:
        pairs = list(entries)
    except TypeError:
        raise InvalidNotification("headers must be a mapping or pairs") from None
    normalized = {}
    for pair in pairs:
        try:
            name, value = pair
        except (TypeError, ValueError):
            raise InvalidNotification("headers must be a mapping or pairs") from None
        normalized.setdefault(_header_text(name, "header name").lower(), value)
    return normalized


def _required_header(normalized, name):
    value = _header_text(normalized.get(name.lower()), name)
    if not value:
        raise InvalidNotification("%s header is missing" % name)
    return value


def _header_text(value, label):
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, (bytes, bytearray, memoryview)):
        try:
            return bytes(value).decode("ascii").strip()
        except UnicodeDecodeError:
            raise InvalidNotification("%s must be ASCII text" % label) from None
    if value is None:
        return ""
    raise InvalidNotification("%s must be text" % label)


def _parse_timestamp(value):
    if _TIMESTAMP.fullmatch(value) is None:
        raise InvalidNotification("%s must be a decimal Unix timestamp" % TIMESTAMP_HEADER)
    return int(value)


def _verify_signature(body, timestamp_header, signature_header, secret):
    """Authenticate the exact received bytes before anything is parsed."""
    match = _SIGNATURE.fullmatch(signature_header)
    if match is None:
        raise InvalidNotification("%s must be %s=<hex digest>" % (SIGNATURE_HEADER, SIGNATURE_SCHEME))
    signed = timestamp_header.encode("ascii") + b"." + body
    expected = hmac.new(_signing_key(secret), signed, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, match.group(1).lower()):
        raise InvalidNotification("signature does not match the delivery")


def _signing_key(secret):
    if isinstance(secret, str):
        return secret.encode("utf-8")
    if isinstance(secret, (bytes, bytearray, memoryview)):
        return bytes(secret)
    raise TypeError("secret must be bytes or str")


def _reject_stale(timestamp, now):
    try:
        now_timestamp = float(now)
    except (TypeError, ValueError):
        raise TypeError("now must be a numeric Unix timestamp") from None
    if not math.isfinite(now_timestamp):
        raise TypeError("now must be a finite Unix timestamp")
    if abs(timestamp - now_timestamp) > MAX_CLOCK_SKEW_SECONDS:
        raise InvalidNotification("delivery timestamp is outside the acceptance window")


def _decode_payload(body):
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidNotification("request body must be UTF-8") from None
    try:
        payload = json.loads(text)
    except ValueError:
        raise InvalidNotification("request body must be a JSON object") from None
    if not isinstance(payload, dict):
        raise InvalidNotification("request body must be a JSON object")
    return payload


def _required_text(payload, field):
    value = payload.get(field)
    if not isinstance(value, str) or not value:
        raise InvalidNotification("%s must be a nonempty string" % field)
    return value


def _required_amount(payload, field):
    value = payload.get(field)
    if isinstance(value, bool) or not isinstance(value, int):
        raise InvalidNotification("%s must be an integer" % field)
    if value < 0:
        raise InvalidNotification("%s must be nonnegative" % field)
    return int(value)


def _required_currency(payload, field):
    value = payload.get(field)
    if not isinstance(value, str) or _CURRENCY.fullmatch(value) is None:
        raise InvalidNotification("%s must be three uppercase ASCII letters" % field)
    return value
