import hashlib, hmac, json, sys
sys.path.insert(0, "src")
from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

SECRET = b"public-test-provider-secret"
NOW = 1760000000
OK = {"event_id": "evt", "account_id": "acct", "amount_minor": 5, "currency": "USD"}
b = json.dumps(OK).encode()
stamp = str(NOW)
good = hmac.new(SECRET, stamp.encode() + b"." + b, hashlib.sha256).hexdigest()
H = {"X-Pay-Timestamp": stamp, "X-Pay-Signature": "v1=" + good}

# str secret on the verifier side only (body signed with the same secret as bytes)
try:
    r = parse_payment(b, H, SECRET.decode(), NOW)
    print("PASS  str secret accepted ->", r == OK)
except Exception as e:
    print("FAIL  str secret ->", type(e).__name__, e)

# genuinely wrong secret on the verifier side
for bad in (b"other-secret", b"", SECRET + b"x"):
    try:
        r = parse_payment(b, H, bad, NOW)
        print("FAIL  secret %r accepted -> %s" % (bad, r))
    except InvalidNotification:
        print("PASS  secret %r rejected" % (bad,))

# duplicate signature headers: first pair wins, attacker-supplied second is ignored
pairs = list(H.items()) + [("X-Pay-Signature", "v1=" + "0" * 64)]
try:
    parse_payment(b, pairs, SECRET, NOW)
    print("PASS  duplicate header pairs handled (valid one wins)")
except InvalidNotification as e:
    print("NOTE  duplicate header pairs rejected:", e)

# non-bytes secret types fail closed rather than silently coercing
for bad in (None, 5, ["k"]):
    try:
        parse_payment(b, H, bad, NOW)
        print("FAIL  secret %r accepted" % (bad,))
    except (TypeError, InvalidNotification) as e:
        print("PASS  secret %r -> %s" % (bad, type(e).__name__))
